'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const routes=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];
const names=[['Ice · solid','冰 · 固態'],['Water · liquid','水 · 液態'],['Water vapour · gas','水蒸氣 · 氣態']];
let variant=OrionProgress.variant('water'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,phase=0,solved=false,hintDepth=0,state='ready',history=[],saveFailed=false;
function initial(v=variant,s=stage){return routes[v][s];}function target(v=variant,s=stage){return routes[v][(s+1)%3];}
function transition(p,d){return Math.max(0,Math.min(2,p+d));}
const changes={'01':['Melting: ice became liquid water.','融化：冰變成液態水。'],'12':['Evaporation: liquid water became invisible water vapour.','蒸發：液態水變成看不見的水蒸氣。'],'21':['Condensation: water vapour became liquid water.','凝結：水蒸氣變成液態水。'],'10':['Freezing: liquid water became ice.','凝固：液態水變成冰。']};
function resetTrial(){phase=initial();solved=false;hintDepth=0;state='ready';history=[];saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('water')){variant=v;stage=0;resetTrial();}
function act(d){if(solved||![-1,1].includes(d))return;const old=phase;phase=transition(phase,d);if(old===phase)state='limit';else{history.unshift(String(old)+phase);history=history.slice(0,6);state='changed';}render();}
function check(){if(solved)return;if(phase!==target()){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('transformation');render();if(stage<2)$('next').focus();}
function hints(){return[t('Watch the form of the water, then compare it with the requested form.','觀察水的形態，再和指定形態比較。'),t('Adding warmth can melt ice or help liquid water evaporate. Cooling can condense vapour or freeze liquid water.','加暖可以融冰或幫助液態水蒸發。冷卻可以讓水蒸氣凝結，或讓液態水結冰。'),phase===target()?t('The forms match. Store this form to open the seal.','形態配對成功。收藏這個形態，打開封印。'):t(`Use ${phase<target()?'Warm':'Cool'} & wait ${Math.abs(phase-target())} time(s), then store the form.`,`使用「${phase<target()?'加暖':'冷卻'}並等待」${Math.abs(phase-target())} 次，再收藏形態。`)];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Cloudkeeper’s Vault · Orion','雲守者的水之密庫 · Orion');$('stageTitle').textContent=t(`Seal ${stage+1} · Journey ${variant+1}`,`第 ${stage+1} 道封印 · 旅程 ${variant+1}`);$('sceneStatus').textContent=complete?t('The water vault is awake.','水之寶庫甦醒了。'):t(`Forms restored · ${count} / 3`,`已修復 ${count} / 3 個形態`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('progressCount').textContent=$('sceneStatus').textContent;$('progressBar').value=count;$('scene').classList.toggle('complete',complete);$('mission').textContent=t('Change the sample into the requested form. Try warming or cooling, then store it.','把樣本變成指定形態。試試加暖或冷卻，再收藏它。');$('sampleName').textContent=t(...names[phase])+(phase===2?t(' · Dots are a model; vapour is invisible.',' · 圓點只是模型；水蒸氣看不見。'):'');$('sampleArt').innerHTML=phase===0?'❄':phase===1?'💧':'<span class="vapour-dots" aria-hidden="true">· · ·</span>';$('vessel').className='vessel '+['ice','liquid','gas'][phase];$('vessel').setAttribute('aria-label',t(...names[phase])+(phase===2?t('. Invisible in real life; dots are a model.','。真實情況下看不見；圓點只是模型。'):''));$('goal').innerHTML=`${t('Requested form','指定形態')}<span class="symbol" aria-hidden="true">${['❄','💧','· · ·'][target()]}</span><strong>${t(...names[target()])}</strong>`;
 const msg={ready:t('The chamber holds the same water throughout. What will your tool change?','容器一直保留同樣的水。你的工具會改變甚麼？'),changed:t(...changes[history[0]]||['','']),limit:t('No further form change in this model. Try the other tool.','這個模型中不會再改變形態。試試另一個工具。'),wrong:t('Not the requested form yet. Compare the labels and try again.','還不是指定形態。比較標籤，再試一次。'),success:t('Form matched! A crystal seal opens.','形態配對成功！一道水晶封印打開了。')};$('feedback').textContent=msg[state];$('log').innerHTML=history.map(k=>`<li>${t(...changes[k])}</li>`).join('')||`<li>${t('Your discoveries will appear here.','你的發現會記錄在這裡。')}</li>`;for(const id of ['warm','cool','check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('transformation')?t('Transformation Sigil saved in your collection.','幻化符印已存入收藏。'):'';
}
$('warm').onclick=()=>act(1);$('cool').onclick=()=>act(-1);$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('warm').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('water',variant);observedVariant=OrionProgress.variant('water');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('transformation');render();};
function syncProgress(){const v=OrionProgress.variant('water'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('transformation')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
